import { useState } from "react";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { PasswordInput } from "@/registry/erbium/ui/password-input";

export default function PasswordInputControlledExample() {
  const [visible, setVisible] = useState(false);

  return (
    <FieldGroup className="max-w-sm">
      <Field>
        <FieldLabel>New password</FieldLabel>
        <PasswordInput autoComplete="new-password" visible={visible} onVisibleChange={setVisible} />
      </Field>
      <Field>
        <FieldLabel>Confirm password</FieldLabel>
        <PasswordInput autoComplete="new-password" visible={visible} onVisibleChange={setVisible} />
      </Field>
      <Field orientation="horizontal">
        <Checkbox
          checked={visible}
          onCheckedChange={(checked) => {
            setVisible(checked);
          }}
        />
        <FieldLabel>Show passwords</FieldLabel>
      </Field>
    </FieldGroup>
  );
}

import PasswordInputControlled from "../examples/password-input-controlled";

const Example = () => <PasswordInputControlled />;

export default Example;
